import os, json, math
from decimal import Decimal, ROUND_HALF_UP
HERE = os.path.dirname(os.path.abspath(__file__))
N = json.load(open(os.path.join(HERE, "numbers_brsh.json"), encoding="utf-8"))
M = N["main"]
def r3(x):
    s = str(Decimal(repr(float(x))).quantize(Decimal("0.001"), rounding=ROUND_HALF_UP))
    return str(Decimal(repr(float(x))).quantize(Decimal("0.0001"), rounding=ROUND_HALF_UP)) if s == "1.000" and abs(float(x) - 1) >= 0.00005 else s
def o(v):
    d = v if isinstance(v, dict) else M[v]; return f"OR {r3(d['OR'])}, 95% CrI {r3(d['lo'])}–{r3(d['hi'])}"
def oa(v):
    d = v if isinstance(v, dict) else M[v]; return f"{r3(d['OR'])}; {r3(d['lo'])}–{r3(d['hi'])}"
def pct(x): return f"{100*x:.0f}%"
def pp(v):
    p = N["sr_mean_all"] / 100; return abs(100 * p * (1 - p) * math.log(M[v]["OR"]))
def _rng(xs, f=lambda x: f"{100*x:.0f}%"):
    a, b = min(xs), max(xs); return f(a) if f(a) == f(b) else f"{f(a)}–{f(b)}"
W, MV, FAC, SM, DR, ED, LIV, DEN, MF = ("walking_practice_rate", "moderate_pa_rate", "public_sports_facilities_per_100k", "current_smoking_rate",
    "high_risk_drinking_rate_drinkers", "tertiary_educated_share", "basic_livelihood_rate", "dentists_per_100k", "ext__manufacturing_share")
HYP = [W, MV, FAC, SM, DR, ED, LIV, DEN, MF]
LABEL = {W: "Walking", MV: "Moderate or vigorous physical activity", FAC: "Public sports facilities per 100,000", SM: "Current smoking",
         DR: "High-risk drinking among drinkers", ED: "Tertiary education", LIV: "Basic livelihood benefit receipt", DEN: "Dentists per 100,000 (log)",
         MF: "Manufacturing share of employment", "urban_population_share": "Urban-zone population share", "clinics_per_100k": "Clinics per 100,000",
         "sex_ratio": "Sex ratio", "fiscal_independence": "Fiscal independence", "pop80_share": "Population aged 80 years or older",
         "fires_per_10000": "Fires per 10,000", "multicultural_marriage_share": "Multicultural marriage share", "rear_seatbelt_wearing_rate": "Rear seat-belt use"}
GROUPS = [("Physical activity", [W, MV, FAC]), ("Other health behaviours", [SM, DR]), ("Social and work conditions", [ED, LIV, MF]), ("Dental supply", [DEN]),
          ("Controls", ["urban_population_share", "clinics_per_100k", "sex_ratio", "fiscal_independence", "pop80_share"])]
SIDO = {"강원도": "Gangwon", "경기도": "Gyeonggi", "서울시": "Seoul", "전라남도": "South Jeolla", "인천시": "Incheon", "경상남도": "South Gyeongsang", "경상북도": "North Gyeongsang",
        "대구시": "Daegu", "제주도": "Jeju", "충청남도": "South Chungcheong", "충청북도": "North Chungcheong", "전라북도": "North Jeolla", "대전시": "Daejeon", "울산시": "Ulsan",
        "광주시": "Gwangju", "부산시": "Busan", "세종시": "Sejong"}
def sido_list(d, k): return ", ".join(f"{SIDO[a]} ({b})" for a, b in list(d.items())[:k])
SR = N["sr"]; G = N.get("gap", {}); SL = N.get("slope", {}); RU = N.get("rural", {}); RO = N.get("rural_OR", {}); KH = lambda m, v: N["kh"][f"{m}|{v}"]; BW = lambda v, c: N["bw"][f"{v}|{c}"]
MVS = N["mv"]; ROB = N["robust"]
assert ROB == [W, SM, DR, ED], ROB
RHO = N["rank_rho"]
MVRANGE = _rng([MVS[v]["cred"] for v in ROB]); SGRANGE = _rng([MVS[v]["sign"] for v in ROB])
CONTROL_SENT = f"Among the controls, the urban-zone population share ({o('urban_population_share')}) and the share aged 80 years or older ({o('pop80_share')}) were credible."

TITLE = "Does toothbrushing after lunch go together with other health behaviours across Korean districts?"
SHORT = "Toothbrushing after lunch across districts"
KEYWORDS = ["toothbrushing", "oral hygiene", "health behaviour", "small-area estimation", "spatial analysis", "Republic of Korea"]

ABSTRACT = [
 ("Objective", "To describe the district geography of toothbrushing after lunch among Korean adults and its relation to other health behaviours and social conditions."),
 ("Basic research design", "Ecological panel of repeated cross-sectional survey estimates, 2014–2024, analysed with a spatio-temporal Fay–Herriot model treating published sampling variances as known."),
 ("Participants", f"Adults aged 19 years or older in the Korea Community Health Survey in all 229 districts ({N['n_resp_total']:,} responses)."),
 ("Main outcome measures", "Age-sex-standardised prevalence of toothbrushing after lunch on the previous day; nine prespecified district covariates."),
 ("Results", f"Mean district prevalence rose from {SR['2014']}% (2014) to {SR['2019']}% (2019), {SR['2020']}% (2020) and {SR['2024']}% (2024); the 90th to 10th percentile ratio of district means was {N['p9010']:.2f}. "
             f"Prevalence was spatially clustered (Moran's I {N['moran']:.2f}) and district ranks were moderately persistent. Per standard deviation (odds ratio; 95% credible interval), walking ({oa(W)}) and tertiary education ({oa(ED)}) were associated with more toothbrushing, and current smoking ({oa(SM)}) and high-risk drinking ({oa(DR)}) with less; these held in random covariate subsets, space-time interaction models and leave-one-province-out models, but walking lost credibility with restricted spatial regression and smoking and drinking with one-year lags. "
             "Other covariates had intervals including 1. Rear seat-belt use, a negative control, was also associated, so the associations are not specific to oral hygiene."),
 ("Conclusions", "Districts with more walking, less smoking, less high-risk drinking and more tertiary education had more toothbrushing after lunch. Midday oral hygiene and other health behaviours were distributed together across districts, which may help to identify districts where several behaviours lag."),
]

INTRO = [
 "Toothbrushing with fluoride toothpaste is the main self-care measure against dental caries and periodontal disease, which remain among the most common diseases worldwide [@peres2019oral]. Poor oral hygiene is associated with periodontitis [@lertpimonchai2017association], and in a Korean cohort brushing three or more times a day was associated with a lower risk of stroke [@chang2021better]. The Korea Community Health Survey has tracked toothbrushing after lunch as a district indicator since 2014; for many adults this brushing occasion falls in the working day rather than in the home routine.",
 "Toothbrushing after lunch differs from morning and evening brushing. In a multilevel analysis of the Korea Community Health Survey, adults in office work were much more likely than manual, service and agricultural workers to brush after lunch, the occupational gap was small for brushing after dinner, and brushing at both times varied between districts [@lee2023factors]. Lower health literacy has been associated with not brushing after lunch among older adults after adjustment for sociodemographic factors [@son2026health], and school-based brushing after lunch fell sharply during the COVID-19 pandemic [@son2026toothbrushing]. Habit theory holds that toothbrushing becomes habitual when it is repeated in response to a cue within a stable context [@raison2021toothbrushing]; the midday context depends on where people work and study.",
 "Health behaviours tend to co-occur. Among Australian adults, less frequent toothbrushing clustered with smoking, physical inactivity and other risk behaviours [@sanders2005clustering], and among Brazilian adolescents less frequent toothbrushing clustered with smoking, drinking and not wearing a seat belt [@jordao2018clustering]. If such clustering is present at the area level, oral hygiene promotion could be combined with general health promotion in the same places. Workplace oral health promotion has improved clinical indicators such as plaque accumulation [@bakri2023oral], but its reach depends on the structure of local employment.",
 "District-level evidence over time is lacking. This study asked whether toothbrushing after lunch among adults clustered and persisted among Korean districts between 2014 and 2024 and whether it varied with walking and other physical activity, smoking and drinking, education, deprivation, dentist supply and manufacturing employment.",
]

METHOD = [
 "This ecological panel study followed the STROBE guideline [@vonelm2007strengthening] and used annual data for the 229 districts (si-gun-gu) of Korea, 2014–2024. The Korea Community Health Survey interviews a probability sample of about 900 adults aged 19 years or older in every district each year [@kang2015korea]; the Korea Disease Control and Prevention Agency publishes district estimates [@web:kdca2026kchs]. Only published aggregate statistics were used.",
 f"The outcome was the age-sex-standardised prevalence of toothbrushing after lunch on the previous day (standard population, 2005 projected population) with its published standard error. The indicator starts in 2014. For Sejong, which was missing from the compiled data set, prevalence and respondent numbers were taken from the published table, and the standard error was derived from the binomial standard error multiplied by the median ratio of published to binomial standard errors in other districts in the same year. All {N['n_cells']:,} district-years were observed (median {N['n_resp_median']} respondents per district-year; districts with several community health centres have larger samples). The survey is a repeated cross-section, so the panel follows districts, not individuals. Mean district prevalence rose by about 14 percentage points between 2019 and 2020, and the rank correlation of district prevalence between these years ({RHO['2019-2020']:.2f}) was slightly lower than between other adjacent years ({min(v for k, v in RHO.items() if k != '2019-2020'):.2f}–{max(v for k, v in RHO.items() if k != '2019-2020'):.2f}). Because the reasons for the 2020 change could not be established from published estimates, it was absorbed by year effects and examined with separate periods and exclusion of 2020–2021.",
 "Nine covariates and their expected directions were fixed before model fitting. Under a health behaviour clustering hypothesis, toothbrushing was expected to be more common where adults walk (≥30 minutes on ≥5 days in the previous week) and engage in moderate or vigorous physical activity, where public sports facilities are denser, and where current smoking and high-risk drinking among drinkers are less common (standardised survey prevalences). Tertiary education and dentist density were expected to be positively associated and basic livelihood benefit receipt and the manufacturing share of employment, a proxy for workplaces with fewer opportunities to brush at midday [@lee2023factors], negatively associated. Five controls were always included: the urban-zone population share, clinics per 100,000 residents, the sex ratio, fiscal independence and the share aged 80 years or older. Moderate or vigorous activity, not published for 2018, was interpolated; manufacturing employment, available from 2017, was carried back to 2014; dentist density was log-transformed, and all covariates were standardised (Supplementary Table S1).",
 "A spatio-temporal Fay–Herriot model was fitted on the logit scale [@fay1979estimates]. The observed logit prevalence was assumed to be normal around a linear predictor with known sampling variance obtained from the published standard error by the delta method. The predictor contained the covariates, a Besag–York–Mollié 2 spatial effect on a contiguity graph with island districts linked to their nearest district [@riebler2016intuitive], a first-order random walk and an independent effect for year, and an independent district-year error. Models were fitted by integrated nested Laplace approximation [@rue2009approximate] in R 4.6.0. Associations are reported as odds ratios (ORs) per standard deviation with 95% credible intervals (CrIs); an interval excluding 1 was termed credible. A separate model added a spatially structured district-specific linear trend to describe district trends (Figure 1D). Spatial structure was described with Moran's I, the rank correlation between 2014–2016 and 2022–2024 and Kendall's W; districts whose spatial effect had a posterior probability of being positive above 0.95 or below 0.05 were classed as high or low.",
 "A covariate was judged robust, by criteria set before fitting, when it was credible in at least 75% of 200 random covariate subsets (each covariate included with probability 0.5) with at least 95% sign agreement [@steegen2016increasing] and remained credible in Knorr-Held type II and type IV space-time interaction models [@knorrheld2000bayesian]. Further checks were a type III model, a between-district and within-district decomposition, lags of one and two years, leaving out each province, binomial, beta and unweighted Gaussian likelihoods and crude prevalence, a queen contiguity graph and an alternative prior, restricted spatial regression, separate periods 2014–2019 and 2020–2024, exclusion of 2020–2021, adjustment for county status and population density, and exclusion of influential district-years. Fires, multicultural marriage and rear seat-belt use, used as negative-control covariates across this series of district analyses, were added one at a time to detect shared bias [@lipsitch2010negative].",
 "The institutional review board approved the study and waived informed consent because only published aggregate statistics were used (details on the title page). Generative artificial intelligence tools (Claude, Anthropic; ChatGPT, OpenAI) were used only for translation and English-language editing; the author reviewed all output and takes full responsibility for the content.",
]

RSR = N.get("rsr", {}); RUR = RO
def nrsr(v): return RSR.get(v, {}).get("cred")
RESULTS = [
 f"Mean district prevalence rose from {SR['2014']}% in 2014 to {SR['2019']}% in 2019, {SR['2020']}% in 2020 and {SR['2024']}% in 2024 (Figure 3). The 90th to 10th percentile ratio of district means over the period was {N['p9010']:.2f}, and the yearly ratio was {G['2014']['ratio']:.2f} in 2014 and {G['2024']['ratio']:.2f} in 2024 (Supplementary Table S5). Prevalence clustered spatially (Moran's I {N['moran']:.2f}, P = 0.001; yearly {N['moran_ymin']:.2f}–{N['moran_ymax']:.2f}); the rank correlation between 2014–2016 and 2022–2024 was {N['persist']:.2f}, and Kendall's W was {N['kendallW']:.2f}. Standardised prevalence was highest in Daejeon, Sejong and Gwangju (Figure 1A; Figure 3). With controls only, {N['n_hot0']} districts were classed as high and {N['n_cold0']} as low (Figure 1B). In the main model, {N['n_hot']} districts were high, mostly in {sido_list(N['hot_sido'], 4)}, and {N['n_cold']} were low, mostly in {sido_list(N['cold_sido'], 3)} (Figure 1C). District-specific trends are shown in Figure 1D. Residual Moran's I was {N['fit']['resid_moran_I']:.2f} (two-sided P = {N['fit']['resid_moran_p']:.2f}). Excluding year effects, covariates accounted for {N['vp_notime']['hypothesis']:.0f}% of the variance of the model components, controls for {N['vp_notime']['forced']:.0f}%, spatial effects for {N['vp_notime']['spatial']:.0f}%, district-year error for {N['vp_notime']['cell']:.0f}% and sampling error for {N['vp_notime']['sampling']:.0f}%. Table 1 near here. Figure 1 near here.",
 f"Four of the nine covariates were credible in the main model (Table 2, Figure 2): walking ({o(W)}), tertiary education ({o(ED)}), current smoking ({o(SM)}) and high-risk drinking ({o(DR)}). At the mean prevalence of {N['sr_mean_all']}%, these correspond to {min(pp(v) for v in ROB):.1f}–{max(pp(v) for v in ROB):.1f} percentage points per standard deviation. All four met the robustness criteria: each was credible in {MVRANGE} of the random specifications containing it with {SGRANGE} sign agreement and in the type II, III (Supplementary Table S2) and IV models, and all four were credible in all {N['loo_n']} leave-one-province-out models. Walking and smoking were credible both between and within districts, high-risk drinking within districts only, and education between districts (lower limit close to 1) but not within districts. Education remained credible with one-year and two-year lags, walking with a one-year lag only, and smoking and drinking with neither. All four had credible intervals excluding 1 in both 2014–2019 and 2020–2024, and interaction terms for the period from 2020 had credible intervals including 1; all four also remained credible when 2020–2021 were excluded. {CONTROL_SENT} Table 2 near here. Figure 2 near here.",
 f"Moderate or vigorous physical activity ({o(MV)}), public sports facilities ({o(FAC)}), dentist density ({o(DEN)}), the manufacturing share of employment ({o(MF)}) and benefit receipt ({o(LIV)}) had credible intervals including 1. Of the negative controls, rear seat-belt use was credible ({o(N['neg']['rear_seatbelt_wearing_rate'])}), and fires and multicultural marriage were not. "
 + "RSR_SENT URBAN_SENT Further sensitivity analyses are in Supplementary Tables S2–S4.",
]

DISCUSSION = [
 "Toothbrushing after lunch became more common among Korean adults between 2014 and 2024. Differences between districts were small in absolute terms, spatially clustered and moderately persistent. Districts with more walking, less smoking, less high-risk drinking among drinkers and more tertiary education had more toothbrushing after lunch, and these associations met the prespecified robustness criteria, although that of walking did not withstand restricted spatial regression. The associations of physical activity infrastructure, dentist supply, manufacturing employment and deprivation were uncertain.",
 "The findings are consistent with individual-level evidence that oral and general health behaviours cluster [@sanders2005clustering; @jordao2018clustering], although district associations do not show that the same people adopt several behaviours. The association with rear seat-belt use, a negative control, means that the associations are not specific to oral hygiene. It may reflect a general pattern of protective behaviour, with which seat-belt use also clustered among individuals in an earlier study [@jordao2018clustering], but it may equally reflect shared bias, such as socially desirable reporting or differences in survey administration between community health centres, because the outcome and the behavioural covariates came from the same survey. The associations of smoking and drinking were not seen with lags, and that of drinking was confined to within-district variation, so they may partly reflect shared year-to-year variation in survey responses; walking and smoking were associated both between and within districts.",
 "The positive association with education agrees with individual-level evidence that office work and health literacy favour brushing after lunch [@lee2023factors; @son2026health]. Manufacturing employment was an indirect proxy for midday working conditions: it describes the industries located in a district rather than where residents work, it was carried back for 2014–2016, and its uncertain association does not exclude a role for working conditions. Once social and behavioural conditions were considered, the capital region and Busan had fewer adults brushing after lunch than expected, and districts in the Chungcheong provinces, the Jeolla provinces and South Gyeongsang more. Whether local oral health programmes or survey administration explain these residual differences cannot be determined here.",
 "The step increase in 2020 coincided with the COVID-19 pandemic. Among children, brushing after lunch declined at that time [@son2026toothbrushing], whereas adult prevalence rose; whether this reflects working from home, attention to hygiene or changes in survey administration cannot be established from published estimates. District ranks were only slightly less stable across 2019–2020 than across other years, and the four associations were present in both periods, but comparability of the indicator before and after 2020 remains uncertain.",
 "The study covered all districts over 11 years, accounted for sampling error in the survey estimates and tested associations against space-time interaction, random covariate subsets and negative controls. Its limitations are those of an ecological design: district associations do not describe individuals [@greenland1989ecological]. Toothbrushing was self-reported for one day and does not measure brushing quality or fluoride use. The behavioural covariates came from the same survey as the outcome and carry their own sampling error, Sejong's standard errors were derived, manufacturing employment was carried back for 2014–2016, and public oral health programmes and fluoride exposure were not measured. Outcome values were checked against the published tables, but the covariates came from a compiled district database. The effects per standard deviation were small, consistent with the narrow range of district prevalence.",
]
CONCLUSION = "Toothbrushing after lunch varies modestly between Korean districts. Districts with more walking, less smoking, less high-risk drinking among drinkers and more tertiary education had more toothbrushing after lunch, but a negative-control behaviour showed the same pattern, so the associations are not specific to oral hygiene. District indicators of several health behaviours could be monitored together to identify districts where oral hygiene and other behaviours lag; whether combined promotion works needs evaluation."
